                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 5 and not visited[nr][nc]:
                            visited[nr][nc] = True
                            q.append((nr, nc))

                # Skip single-cell regions
                if len(region) < 2:
                    continue

                # Find bounding box
                min_r, max_r = min(r for r, c in region), max(r for r, c in region)
                min_c, max_c = min(c for r, c in region), max(c for r, c in region)

