                region = []
                q = deque([(start_r, start_c)])
                visited[start_r][start_c] = True
                while q:
                    r, c = q.popleft()
                    region.append((r, c))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 5 and not visited[nr][nc]:
                            visited[nr][nc] = True
                            q.append((nr, nc))

                if len(region) < 2:
                    continue

                min_r, max_r = min(r for r, c in region), max(r for r, c in region)
                min_c, max_c = min(c for r, c in region), max(c for r, c in region)

                if max_r - min_r < 2 or max_c - min_c < 2:
                    continue

                # Fill interior 0s
                for r in range(min_r + 1, max_r):
